# A package (or, in a single package, a component) and every package that depends on it,
# from the architecture's dependency rules.
pkg_scope() {
  case "$1" in
    core) echo "core snake corridor agent baselines evaluate runs train registry curves replay study" ;;
    snake) echo "snake baselines registry replay study" ;;
    corridor) echo "corridor registry replay study" ;;
    agent) echo "agent runs train registry curves replay study" ;;
    baselines) echo "baselines registry replay study" ;;
    evaluate) echo "evaluate runs train registry curves replay study" ;;
    runs) echo "runs train registry curves replay study" ;;
    train) echo "train study" ;;
    registry) echo "registry replay study" ;;
    curves) echo "curves study" ;;
    replay) echo "replay" ;;
    study) echo "study" ;;
    cli) echo "cli" ;;
    *) return 1 ;;
  esac
}

